import subprocess
result = subprocess.run(['pdftotext', '-layout', 'main.pdf', '-'], capture_output=True, text=True)
text = result.stdout
pages = text.split('\f')
for i, page in enumerate(pages):
    if 'References' in page:
        for line in page.split('\n'):
            if line.strip() == 'References':
                print(f"'References' header found on page {i+1}")
                break
    if 'Limitations' in page:
        for line in page.split('\n'):
            if line.strip() == 'Limitations':
                print(f"'Limitations' header found on page {i+1}")
                break
    if 'Discussion and Conclusion' in page:
        for line in page.split('\n'):
            if 'Discussion and Conclusion' in line.strip():
                print(f"'Discussion and Conclusion' found on page {i+1}")
                break
print(f"Total pages: {len(pages)}")
EOF
